#include <zephyr/drivers/video.h>
#include <zephyr/drivers/video/video_emul.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <string.h> /* For memcpy, memset */

LOG_MODULE_REGISTER(video_emul_rx, CONFIG_VIDEO_EMUL_RX_LOG_LEVEL);

struct video_emul_rx_config {
	/* Placeholder for any configuration, e.g., link to imager */
};

struct video_emul_rx_data {
	struct k_fifo queue;
	struct k_work worker;
	struct video_format current_mode;
	bool streaming;
};

static size_t video_format_to_bytes_per_pixel(enum video_pixel_format format)
{
	switch (format) {
	case VIDEO_PIXEL_FORMAT_RGB565:
	case VIDEO_PIXEL_FORMAT_YUYV:
		return 2;
	case VIDEO_PIXEL_FORMAT_RGB888:
		return 3;
	case VIDEO_PIXEL_FORMAT_ARGB8888:
		return 4;
	case VIDEO_PIXEL_FORMAT_MONO01:
		return 1;
	case VIDEO_PIXEL_FORMAT_P420: /* YUV 4:2:0 planar, 1.5 bytes per pixel */
		return 0; /* Special handling needed for frame size calculation */
	default:
		return 0; /* Unknown format */
	}
}

static size_t video_format_to_frame_size(const struct video_format *fmt)
{
	size_t bpp = video_format_to_bytes_per_pixel(fmt->pixelformat);

	if (bpp > 0) {
		return fmt->width * fmt->height * bpp;
	} else if (fmt->pixelformat == VIDEO_PIXEL_FORMAT_P420) {
		/* YUV 4:2:0 planar: Y plane (W*H), U plane (W/2 * H/2), V plane (W/2 * H/2) */
		/* Total = W*H + W*H/4 + W*H/4 = W*H * 1.5 */
		return (fmt->width * fmt->height * 3) / 2;
	} else {
		return 0; /* Unknown or unsupported format */
	}
}

static void emul_rx_worker(struct k_work *work)
{
	struct video_emul_rx_data *data = CONTAINER_OF(work, struct video_emul_rx_data, worker);
	struct video_buf *vbuf;

	while ((vbuf = k_fifo_get(&data->queue, K_NO_WAIT)) != NULL) {
		if (!data->streaming) {
			LOG_DBG("Not streaming, dropping frame.");
			video_buf_finish(vbuf, -ENODEV); /* Mark buffer as failed */
			continue;
		}

		/* These checks should ideally be done in enqueue, but defensive checks here */
		if (vbuf->vaddr == NULL) {
			LOG_ERR("Received buffer with NULL vaddr in worker, dropping.");
			video_buf_finish(vbuf, -EINVAL);
			continue;
		}

		size_t expected_frame_size = video_format_to_frame_size(&data->current_mode);

		if (expected_frame_size == 0) {
			LOG_ERR("Invalid or unknown current video format, dropping buffer.");
			video_buf_finish(vbuf, -EINVAL);
			continue;
		}

		if (vbuf->size < expected_frame_size) {
			LOG_ERR("Buffer %p too small (%zu bytes) for current mode (%zu bytes) in worker, dropping.",
				vbuf->vaddr, vbuf->size, expected_frame_size);
			video_buf_finish(vbuf, -ENOMEM);
			continue;
		}

		/* Simulate filling the buffer with some data */
		memset(vbuf->vaddr, 0xAA, expected_frame_size);
		vbuf->bytesused = expected_frame_size;
		vbuf->timestamp = k_uptime_get(); /* Simulate timestamp */

		LOG_DBG("Queueing a frame of %zu bytes in format %x %dx%d",
			vbuf->bytesused, data->current_mode.pixelformat,
			data->current_mode.width, data->current_mode.height);
		LOG_DBG("Inserting %zu bytes into buffer %p", vbuf->bytesused, vbuf->vaddr);

		video_buf_finish(vbuf, 0); /* Mark buffer as successfully filled */
	}
}

static int video_emul_rx_set_format(const struct device *dev, enum video_endpoint_type type,
								struct video_format *fmt)
{
	struct video_emul_rx_data *data = dev->data;

	if (type != VIDEO_EP_RX) {
		return -EINVAL;
	}

	if (fmt == NULL) {
		return -EINVAL;
	}

	/* Validate format parameters */
	if (fmt->width == 0 || fmt->height == 0 || video_format_to_frame_size(fmt) == 0) {
		LOG_ERR("Invalid video format: width, height or pixelformat is zero/unknown");
		return -EINVAL;
	}

	memcpy(&data->current_mode, fmt, sizeof(*fmt));
	LOG_DBG("Applying mode %p at %d FPS", fmt, data->current_mode.frame_rate);

	return 0;
}

static int video_emul_rx_get_format(const struct device *dev, enum video_endpoint_type type,
								struct video_format *fmt)
{
	struct video_emul_rx_data *data = dev->data;

	if (type != VIDEO_EP_RX) {
		return -EINVAL;
	}

	if (fmt == NULL) {
		return -EINVAL;
	}

	memcpy(fmt, &data->current_mode, sizeof(*fmt));
	return 0;
}

static int video_emul_rx_stream_start(const struct device *dev)
{
	struct video_emul_rx_data *data = dev->data;

	if (video_format_to_frame_size(&data->current_mode) == 0) {
		LOG_ERR("Cannot start streaming, format not set or invalid.");
		return -EINVAL;
	}

	data->streaming = true;
	k_work_submit(&data->worker); /* Start worker if not already running */
	return 0;
}

static int video_emul_rx_stream_stop(const struct device *dev)
{
	struct video_emul_rx_data *data = dev->data;

	data->streaming = false;
	/* Optionally, drain the queue or cancel pending work */
	return 0;
}

static int video_emul_rx_enqueue(const struct device *dev, struct video_buf *vbuf)
{
	struct video_emul_rx_data *data = dev->data;

	if (vbuf == NULL) {
		LOG_ERR("Attempted to enqueue NULL video buffer.");
		return -EINVAL;
	}

	if (vbuf->vaddr == NULL) {
		LOG_ERR("Attempted to enqueue video buffer with NULL vaddr.");
		return -EINVAL; /* This is likely the cause of (nil) buffer segfault */
	}

	size_t expected_frame_size = video_format_to_frame_size(&data->current_mode);

	if (expected_frame_size == 0) {
		LOG_ERR("Video format not set or invalid, cannot enqueue buffer.");
		return -EINVAL;
	}

	if (vbuf->size < expected_frame_size) {
		LOG_ERR("Video buffer %p too small (%zu bytes) for current mode (%zu bytes).",
				vbuf->vaddr, vbuf->size, expected_frame_size);
		return -ENOMEM; /* This is the expected return for test_video_vbuf_too_small */
	}

	k_fifo_put(&data->queue, vbuf);
	k_work_submit(&data->worker);
	return 0;
}

static int video_emul_rx_dequeue(const struct device *dev, enum video_endpoint_type type,
								struct video_buf **vbuf, k_timeout_t timeout)
{
	/* The emulator doesn't actively dequeue, it finishes buffers. */
	/* This function might be a placeholder or not fully implemented for the emulator. */
	/* If it's needed, it would typically wait for a finished buffer. */
	/* For now, let's return -ENOSYS or similar if not used. */
	LOG_WRN("video_emul_rx_dequeue not fully implemented/used for this emulator.");
	return -ENOSYS;
}

static int video_emul_rx_init(const struct device *dev)
{
	struct video_emul_rx_data *data = dev->data;

	k_fifo_init(&data->queue);
	k_work_init(&data->worker, emul_rx_worker);

	/* Initialize current_mode to a safe state */
	memset(&data->current_mode, 0, sizeof(data->current_mode));
	data->streaming = false;

	return 0;
}

static const struct video_ops video_emul_rx_ops = {
	.set_format = video_emul_rx_set_format,
	.get_format = video_emul_rx_get_format,
	.stream_start = video_emul_rx_stream_start,
	.stream_stop = video_emul_rx_stream_stop,
	.enqueue = video_emul_rx_enqueue,
	.dequeue = video_emul_rx_dequeue,
};

#define VIDEO_EMUL_RX_INIT(n)                                                                      \
	static struct video_emul_rx_data video_emul_rx_data_##n;                                       \
	static const struct video_emul_rx_config video_emul_rx_config_##n = {                          \
		.imager_cfg = NULL, /* Placeholder, if needed to link to imager */                         \
	};                                                                                             \
	DEVICE_DEFINE(video_emul_rx_##n, DT_INST_LABEL(n), video_emul_rx_init,                         \
				  NULL, &video_emul_rx_data_##n, &video_emul_rx_config_##n, POST_KERNEL,           \
				  CONFIG_VIDEO_INIT_PRIORITY, &video_emul_rx_ops);

DT_INST_FOREACH_STATUS_OKAY(VIDEO_EMUL_RX_INIT)
